/** * VOLUNTEER.JS — Logic riêng cho phân hệ Tình nguyện viên (Volunteer Portal) * Tương tác với: shared/useStorage.js, shared/useToast.js, shared/useTheme.js */ document.addEventListener('DOMContentLoaded', () => { useTheme.init(); renderVolunteerDashboard(); }); // Dữ liệu mẫu đơn đăng ký ban đầu (nếu chưa có trong localStorage) const defaultApps = [ { id: "APP-2026-001", activityTitle: "Ngày hội trồng 1.000 cây xanh vì môi trường", organizer: "Quỹ Xanh Việt Nam", date: "24/10/2026", status: "approved", statusText: "Đã xác nhận", verifiedHours: 6, hasCert: true }, { id: "APP-2026-002", activityTitle: "Tủ sách trao em - Đem tri thức đến trường vùng sâu", organizer: "CLB Ánh Sáng Tương Lai", date: "02/11/2026", status: "pending", statusText: "Chờ duyệt", verifiedHours: 0, hasCert: false } ]; window.cancelApp = function (appId) { if (confirm(`Bạn có chắc chắn muốn hủy đơn đăng ký [${appId}] không?`)) { let apps = useStorage.get('vh_user_apps', defaultApps); apps = apps.filter(a => a.id !== appId); useStorage.set('vh_user_apps', apps); useToast.show('Đã hủy đơn đăng ký thành công.', 'info'); renderVolunteerDashboard(); } }; window.viewCert = function (appId, title) { alert(`📜 CHỨNG NHẬN ĐIỆN TỬ CHÍNH THỨC

Mã xác thực: CERT-${appId}
Hoạt động: ${title}
Người tham gia: Nguyễn Văn An
Tình trạng: ĐÃ XÁC NHẬN HOÀN THÀNH

(Dữ liệu được bảo chứng bởi NhiLun)`); };
